// A pure‐spec function: given a Seq<u64>, extract exactly those entries
// that are divisible by 3, in order.
#[verifier::spec]
fn filter_div3(s: Seq<u64>) -> Seq<u64> {
    s.filter_map(|v: u64| if v % 3 == 0 { Some(v) } else { None })
}

